  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Why Fitness Matters$j$, $j${"readings": [{"title": "1 Corinthians 6 (King James Version)", "url": "/portal/bible/1Corinthians/6"}], "body": "Physical fitness is the ability to do daily tasks with energy and to meet the challenges of the day without being worn out. Physical activity is any movement that uses energy, such as walking, dancing or playing basketball. Exercise is planned, repeated activity done to improve or keep fitness. Fitness is a gift to be cared for. First Corinthians 6:19 and 20 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own? For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's.\n\nRegular activity strengthens the heart and lungs, builds muscle and bone, helps control weight, improves sleep and mood, lowers stress, and lowers the risk of heart disease, type 2 diabetes and some other illnesses. It also helps students think and learn. The Physical Activity Guidelines for Americans advise children and teens ages 6 to 17 to get at least 60 minutes of moderate to vigorous activity every day, mostly aerobic, with vigorous activity, muscle strengthening and bone strengthening each on at least 3 days a week.\n\nBefore you begin any new program, get approval from a parent or guardian, and ask a doctor if you have any health concern, injury or condition. Warm up first. Stop at once if you feel pain, dizziness, trouble breathing or chest pain, and tell an adult. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nYour task: (1) Define physical fitness, physical activity and exercise. (2) Give four benefits of regular activity. (3) State the daily activity guideline for teens and describe how you could meet it this week.\n\nFlorida standards: PE.912.L.3, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, PE.912.R.5", "script": "Welcome to Physical Education with Personal Fitness. I am Dr. Alex L. Jenkins Sr., and I am glad to walk with you as you learn to care for the body God gave you. Listen, fitness is not about looking a certain way. It is about being strong enough to serve, to learn and to live well.\n\nFirst Corinthians 6:19 tells us that our body is the temple of the Holy Ghost. We are to glorify God in our body.\n\nNow watch this. Physical fitness is the ability to do daily tasks with energy. Physical activity is any movement that uses energy. Exercise is planned, repeated activity done to improve fitness.\n\nLook at the benefits. Regular activity strengthens your heart and lungs, builds muscle and bone, helps you sleep, lifts your mood, lowers stress, and helps you think and learn. The national guidelines say teens should get at least 60 minutes of moderate to vigorous activity every day, with muscle strengthening and bone strengthening on at least 3 days a week.\n\nRemember your safety. Get approval from a parent or guardian before you start, and ask a doctor if you have any health concern. Warm up first. Stop right away if you feel pain, dizziness or trouble breathing, and tell an adult. Proverbs 22:3 says a prudent man foreseeth the evil.\n\nYour task is to define fitness, activity and exercise, name four benefits, and plan how to meet the 60 minute guideline this week. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Why Fitness Matters$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 The Parts of Fitness$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "Fitness has two groups of parts. Health related fitness supports overall health. It has five components. Cardiorespiratory endurance is the ability of the heart, lungs and blood vessels to supply oxygen during long activity. Muscular strength is the most force a muscle can use at one time. Muscular endurance is the ability of a muscle to keep working over time without tiring. Flexibility is the range of motion at a joint. Body composition is the share of the body that is fat compared with lean tissue such as muscle, bone and water.\n\nSkill related fitness helps in sports and quick movement. Its parts are agility, which is changing direction quickly, balance, coordination, power, which is strength used fast, reaction time and speed. A sprinter needs power and speed, and a basketball guard needs agility and coordination.\n\nEach person is made differently, and fitness must be judged by health and ability, not by comparison with others. Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well. Body composition is not a measure of worth, and students should never judge themselves or others only by appearance.\n\nSimple checks can show where you stand. Examples are a timed walk or run for cardiorespiratory endurance, a count of push ups for muscular endurance, and a sit and reach for flexibility. Check results again every few weeks to see progress.\n\nYour task: (1) Name and define the five health related components. (2) Name three skill related components and a sport that uses each. (3) Explain why people should not compare their bodies with one another.\n\nFlorida standards: PE.912.C.2, PE.912.L.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.C.2, PE.912.L.3", "script": "Welcome back. Listen, to train well you must know what you are training. Fitness has parts.\n\nHealth related fitness has five components. Cardiorespiratory endurance is how well your heart, lungs and blood vessels supply oxygen during long activity. Muscular strength is the most force a muscle can use at once. Muscular endurance is how long a muscle can keep working. Flexibility is the range of motion at a joint. And body composition is the share of your body that is fat compared with muscle, bone and water.\n\nNow watch this. Skill related fitness helps in sports. Agility is changing direction fast. Balance, coordination, power, reaction time and speed round it out. A sprinter needs power and speed. A basketball guard needs agility and coordination.\n\nLook at Psalm 139:14. I am fearfully and wonderfully made. Every body is different, so measure your fitness by health and progress, not by comparing yourself with someone else. Your worth is never measured by your body fat or your appearance.\n\nYou can check your progress with simple tests, like a timed walk or run, push ups, and a sit and reach. Test again every few weeks.\n\nYour task is to name the five health related parts, name three skill related parts, and explain why we should not compare bodies. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 The Parts of Fitness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 The FITT Principle and Safe Training$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "A good program follows the FITT principle. F is frequency, how often you exercise. I is intensity, how hard you work. T is time, how long each session lasts. The second T is type, the kind of activity you choose. Changing any one of these changes the program.\n\nFour rules guide training. Overload means working a little harder than the body is used to so that it adapts. Progression means increasing the load gradually, not all at once. Specificity means that the body improves in the way it is trained, so running builds running fitness. Reversibility means that fitness fades when you stop, so consistency matters.\n\nEvery session should have three parts. A warm up of 5 to 10 minutes raises body temperature and heart rate with easy movement. The main workout follows. A cool down of 5 to 10 minutes lowers the heart rate slowly and may include light stretching.\n\nSafety is part of fitness. Wear proper shoes and clothing. Drink water before, during and after activity. In South Florida, heat and humidity are real dangers, so exercise in the cooler parts of the day, rest in the shade and learn the signs of heat illness. Do not train through pain. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. Be wary of fads and shortcuts that promise fast results.\n\nYour task: (1) Write what each letter of FITT stands for. (2) Explain overload, progression, specificity and reversibility. (3) List three safety steps for exercising in Florida heat.\n\nFlorida standards: PE.912.C.2, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.C.2, PE.912.R.5", "script": "Welcome back. Listen, wise training has a plan, and the plan has a name: FITT.\n\nF is frequency, how often you exercise. I is intensity, how hard you work. T is time, how long each session lasts. And the second T is type, the kind of activity you choose.\n\nNow watch this. Four rules guide your training. Overload means working a little harder than your body is used to, so it adapts. Progression means adding more gradually, not all at once. Specificity means you improve in the way you train, so running builds running fitness. Reversibility means fitness fades when you stop, so be consistent.\n\nEvery session has three parts. A warm up of five to ten minutes. The main workout. And a cool down of five to ten minutes to bring your heart rate down slowly.\n\nLook at safety. Wear proper shoes. Drink water before, during and after. In South Florida, exercise in the cooler hours, rest in the shade, and learn the signs of heat illness. Never train through pain. Proverbs 14:15 says the prudent man looketh well to his going.\n\nYour task is to explain FITT, the four rules and three heat safety steps. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 The FITT Principle and Safe Training$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Goals and Fitness Assessment$j$, $j${"readings": [{"title": "Philippians 3 (King James Version)", "url": "/portal/bible/Philippians/3"}], "body": "A goal gives your training direction. Apostle Paul wrote in Philippians 3:14, I press toward the mark for the prize of the high calling of God in Christ Jesus. A goal works best when it is a SMART goal: specific, measurable, achievable, relevant and time bound. Compare two goals. Get in shape is vague. Walk or jog for 20 minutes without stopping, 4 days a week, within 8 weeks, is SMART.\n\nBegin with an assessment to find your starting point. Safe and simple choices include the following. Resting heart rate: count the beats at your wrist for 60 seconds in the morning before getting up. A typical resting rate is about 60 to 100 beats a minute, and a lower rate often shows a fitter heart. Cardiorespiratory endurance: time a one mile walk or run, or count laps completed in a set time. Muscular endurance: count how many curl ups or push ups you can do with good form. Flexibility: use the sit and reach test.\n\nRecord every result in a fitness journal with the date. Add a weekly activity log that lists the day, the activity, the minutes and how hard it felt. A log shows progress, keeps you honest and helps you adjust. Celebrate small wins, and if you miss a day, simply begin again. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nYour task: (1) Write one SMART goal for your fitness. (2) Complete two assessments safely and record your results. (3) Start a weekly activity log.\n\nFlorida standards: PE.912.C.2, PE.912.L.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.C.2, PE.912.L.3", "script": "Welcome back. Listen, a runner without a finish line just wanders. A goal gives your training direction.\n\nPaul wrote in Philippians 3:14, I press toward the mark for the prize of the high calling of God in Christ Jesus. Press toward a mark.\n\nNow watch this. A good goal is a SMART goal. Specific. Measurable. Achievable. Relevant. And time bound. Get in shape is vague. Walk or jog for 20 minutes without stopping, 4 days a week, within 8 weeks, is SMART.\n\nLook at how you find your starting point. Resting heart rate, counted at your wrist for a full minute in the morning, usually falls between 60 and 100 beats a minute. A timed one mile walk or run shows your endurance. Push ups or curl ups with good form show muscular endurance. The sit and reach shows flexibility.\n\nWrite every result in a fitness journal with the date, and keep a weekly activity log with the day, the activity, the minutes and how hard it felt. If you miss a day, simply begin again.\n\nProverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nYour task is to write a SMART goal, complete two assessments safely, and start your activity log. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Goals and Fitness Assessment$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Foundations of Fitness$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of fitness. Use complete sentences and label each part. First Corinthians 6:19 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?\n\nPart 1: Define physical fitness, physical activity and exercise, and explain three benefits of regular activity.\nPart 2: Name the five health related components of fitness and describe each in one sentence.\nPart 3: Explain the FITT principle and the four training rules, and give an example of each.\nPart 4: Write one SMART goal for yourself and tell how you will measure it.\nPart 5: Describe your starting point with at least two simple assessments, and list four safety steps you will follow. Attach or describe your first week of activity log entries.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 25 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Foundations of Fitness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: The Body as a Temple$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells what physical activity you enjoy most and why, (2) explains one barrier that keeps teens from being active and one way to overcome it, (3) describes how you will keep safe in the Florida heat, and (4) connects your answer to First Corinthians 6:19 and 20, which says that your body is the temple of the Holy Ghost, and that you should glorify God in your body. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it unwise to judge people by their body size or appearance? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: The Body as a Temple$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Why Fitness Matters$j$, $j${"questions": [{"q": "Exercise is best described as:", "options": ["Planned, repeated activity done to improve fitness", "Watching sports", "Only competitive sports", "Any rest period"]}, {"q": "Teens should get at least how much moderate to vigorous activity each day?", "options": ["10 minutes", "6 hours", "60 minutes", "5 minutes"]}, {"q": "Which is a benefit of regular physical activity?", "options": ["Poorer mood", "Stronger heart and better sleep", "Less energy", "Weaker bones"]}, {"q": "Before starting a new fitness program, a student should:", "options": ["Train until exhausted", "Get approval from a parent or guardian", "Ignore pain", "Skip the warm up"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why Fitness Matters$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,1}'::int[], array[$j$Exercise is structured and repeated to build or keep fitness.$j$,$j$National guidelines advise 60 minutes a day for ages 6 to 17.$j$,$j$Activity improves the heart, bones, sleep and mood.$j$,$j$Adult approval and a doctor's advice when needed keep training safe.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why Fitness Matters$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: The Parts of Fitness$j$, $j${"questions": [{"q": "The ability of a muscle to keep working over time without tiring is:", "options": ["Flexibility", "Reaction time", "Muscular endurance", "Muscular strength"]}, {"q": "Range of motion at a joint is called:", "options": ["Speed", "Body composition", "Power", "Flexibility"]}, {"q": "Which is a skill related component of fitness?", "options": ["Muscular strength", "Agility", "Body composition", "Flexibility"]}, {"q": "Body composition compares:", "options": ["Fat with lean tissue", "Heart rate with time", "Height with age", "Speed with distance"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Parts of Fitness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,0}'::int[], array[$j$Muscular endurance is sustained effort.$j$,$j$Flexibility is how far a joint can move.$j$,$j$Agility is changing direction quickly and belongs to the skill related group.$j$,$j$It is the share of fat compared with muscle, bone and water.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Parts of Fitness$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: The FITT Principle and Safe Training$j$, $j${"questions": [{"q": "In the FITT principle, the first T stands for:", "options": ["Tempo", "Type", "Training", "Time"]}, {"q": "Gradually increasing the amount of exercise is called:", "options": ["Recovery", "Progression", "Specificity", "Reversibility"]}, {"q": "What is the purpose of a cool down?", "options": ["To skip water", "To start training", "To raise the heart rate", "To lower the heart rate slowly"]}, {"q": "Which is a smart way to handle South Florida heat?", "options": ["Avoid water", "Exercise in cooler hours and drink water", "Exercise at noon without rest", "Ignore dizziness"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The FITT Principle and Safe Training$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,1}'::int[], array[$j$FITT stands for frequency, intensity, time and type.$j$,$j$Progression avoids doing too much too soon.$j$,$j$A cool down helps the body return to rest.$j$,$j$Cooler times, shade and fluids lower the risk of heat illness.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The FITT Principle and Safe Training$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Goals and Fitness Assessment$j$, $j${"questions": [{"q": "In a SMART goal, the letter M stands for:", "options": ["Muscular", "Maybe", "Measurable", "Mandatory"]}, {"q": "Which goal is the most SMART?", "options": ["Get in shape", "Run a lot", "Jog 20 minutes, 4 days a week, within 8 weeks", "Be fit someday"]}, {"q": "A typical resting heart rate is about:", "options": ["200 to 220 beats a minute", "10 to 20 beats a minute", "60 to 100 beats a minute", "300 beats a minute"]}, {"q": "Why keep an activity log?", "options": ["It is only for athletes", "It replaces exercise", "It lowers heart rate", "It shows progress and helps you adjust"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Goals and Fitness Assessment$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,3}'::int[], array[$j$A SMART goal can be counted or timed.$j$,$j$It is specific, measurable, achievable, relevant and time bound.$j$,$j$A lower resting rate often shows a fitter heart.$j$,$j$A log records what you do and how you improve.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Goals and Fitness Assessment$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Foundations of Fitness$j$, $j${"questions": [{"q": "Physical activity is:", "options": ["Only lifting weights", "Rest", "Only sports teams", "Any movement that uses energy"]}, {"q": "The Physical Activity Guidelines advise teens to get at least:", "options": ["None on weekdays", "2 hours weekly only", "60 minutes of moderate to vigorous activity daily", "5 minutes daily"]}, {"q": "Which is a health related component of fitness?", "options": ["Speed", "Reaction time", "Agility", "Cardiorespiratory endurance"]}, {"q": "Muscular strength is:", "options": ["A joint's range of motion", "The most force a muscle can use at one time", "Body fat share", "How long a muscle works"]}, {"q": "The I in FITT stands for:", "options": ["Injury", "Inactivity", "Intensity", "Interval"]}, {"q": "Fitness fading when you stop training is called:", "options": ["Specificity", "Overload", "Reversibility", "Progression"]}, {"q": "In a SMART goal, the T stands for:", "options": ["Tough", "Team", "Time bound", "Trying"]}, {"q": "If you feel pain, dizziness or chest pain during exercise, you should:", "options": ["Skip water", "Ignore it", "Push harder", "Stop and tell an adult"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Fitness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,1,2,2,2,3}'::int[], array[$j$Walking, dancing and playing all count.$j$,$j$Sixty minutes a day is the guideline.$j$,$j$The five health related parts include cardiorespiratory endurance.$j$,$j$Strength is maximum force.$j$,$j$Intensity is how hard you work.$j$,$j$Reversibility means that gains are lost without use.$j$,$j$A SMART goal has a deadline.$j$,$j$Safety comes before performance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Fitness$j$ on conflict (item_id) do nothing;
